{"command": "# Check cron jobs related to mempalace
python3 -c "
import json, os
# Look for cron jobs
cron_path = os.path.expanduser('~/.hermes/hermes-agent/config.yaml')
if os.path.exists(cron_path):
    with open(cron_path) as f:
        content = f.read()
    # Check for mempalace-related cron entries
    lines = content.split('\n')
    for i, line in enumerate(lines):
        if 'mempalace' in line.lower() or 'maintenance' in line.lower():
            # Show context
            start = max(0, i-3)
            end = min(len(lines), i+4)
            print(f'Lines {start}-{end}:')
            for j in range(start, end):
                print(f'  {j+1}: {lines[j]}')
            print('---')
" 2>&1 | head -50"}

